import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getShowById, getSchedulesByShow, getAllVenues } from '../../services/api';

// Shows entity: showId, title, showType, genre, duration, language
// Schedule entity: scheduleId, showId, venueId, showDate, showTime

export default function ShowDetailPage() {
  const { showId } = useParams();
  const navigate = useNavigate();
  const [show, setShow] = useState(null);
  const [schedules, setSchedules] = useState([]);
  const [venues, setVenues] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedDate, setSelectedDate] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [s, sc, v] = await Promise.allSettled([
          getShowById(showId),
          getSchedulesByShow(showId),
          getAllVenues(),
        ]);
        if (s.status === 'fulfilled') setShow(s.value.data);
        if (sc.status === 'fulfilled') setSchedules(sc.value.data || []);
        if (v.status === 'fulfilled') setVenues(v.value.data || []);
      } catch {}
      setLoading(false);
    };
    fetchData();
  }, [showId]);

  const getVenueName = (venueId) => venues.find(v => v.venueId === venueId)?.venueName || `Venue #${venueId}`;
  const getVenueCity = (venueId) => venues.find(v => v.venueId === venueId)?.city || '';

  // Get unique dates from schedules
  const dates = [...new Set(schedules.map(s => s.showDate).filter(Boolean))];
  const filteredSchedules = selectedDate ? schedules.filter(s => s.showDate === selectedDate) : schedules;

  if (loading) return <div className="user-page"><div className="spinner" /></div>;
  if (!show) return <div className="user-page"><div className="empty-state"><div className="empty-icon">❌</div><p>Show not found.</p></div></div>;

  return (
    <div className="user-page fade-in">
      <button className="btn btn-ghost" style={{ marginBottom: 24, padding: '7px 14px', fontSize: 13 }} onClick={() => navigate(-1)}>
        ← Back
      </button>

      {/* Show Info */}
      <div className="card" style={{ marginBottom: 36, display: 'grid', gridTemplateColumns: '160px 1fr', gap: 28 }}>
        <div style={{ background: 'linear-gradient(135deg, rgba(212,175,55,0.1), rgba(26,188,156,0.05))', borderRadius: 12, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 56, minHeight: 160 }}>
          {show.showType === 'MOVIE' ? '🎬' : show.showType === 'CONCERT' ? '🎵' : '🎪'}
        </div>
        <div>
          <span className="badge badge-gold" style={{ marginBottom: 12, display: 'inline-block' }}>{show.showType}</span>
          <h1 style={{ fontSize: '2rem', marginBottom: 10 }}>{show.title}</h1>
          <div style={{ display: 'flex', gap: 16, marginBottom: 16, flexWrap: 'wrap' }}>
            {show.genre && <span style={{ color: 'var(--text-secondary)', fontSize: 14 }}>🎭 {show.genre}</span>}
            {show.language && <span style={{ color: 'var(--text-secondary)', fontSize: 14 }}>🌐 {show.language}</span>}
            {show.duration > 0 && <span style={{ color: 'var(--text-secondary)', fontSize: 14 }}>⏱ {show.duration} min</span>}
          </div>
        </div>
      </div>

      {/* Schedules */}
      <h2 style={{ fontSize: '1.4rem', marginBottom: 20 }}>Available Schedules</h2>

      {/* Date filter */}
      {dates.length > 0 && (
        <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap' }}>
          <button className={`btn ${!selectedDate ? 'btn-primary' : 'btn-ghost'}`} style={{ padding: '7px 14px', fontSize: 13 }} onClick={() => setSelectedDate('')}>
            All Dates
          </button>
          {dates.sort().map(d => (
            <button key={d} className={`btn ${selectedDate === d ? 'btn-primary' : 'btn-ghost'}`} style={{ padding: '7px 14px', fontSize: 13 }} onClick={() => setSelectedDate(d)}>
              {new Date(d).toLocaleDateString('en-IN', { weekday: 'short', day: 'numeric', month: 'short' })}
            </button>
          ))}
        </div>
      )}

      {filteredSchedules.length === 0 ? (
        <div className="empty-state"><div className="empty-icon">📅</div><p>No schedules available yet.</p></div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          {filteredSchedules.map(s => (
            <div key={s.scheduleId} className="card"
              style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '20px 24px', cursor: 'pointer' }}
              onClick={() => navigate(`/portal/seats/${s.scheduleId}`, { state: { schedule: s, show, venues } })}>
              <div>
                <div style={{ fontWeight: 600, marginBottom: 4 }}>
                  {s.showDate ? new Date(s.showDate).toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }) : '—'}
                </div>
                <div style={{ fontSize: 14, color: 'var(--gold)', fontWeight: 600 }}>🕐 {s.showTime || '—'}</div>
                <div style={{ fontSize: 13, color: 'var(--text-muted)', marginTop: 4 }}>
                  📍 {getVenueName(s.venueId)}{getVenueCity(s.venueId) ? ` — ${getVenueCity(s.venueId)}` : ''}
                </div>
              </div>
              <button className="btn btn-primary">Select Seats →</button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
